    26  remove_sign_bits(char *str, int base)
    27  {
    28    char *t;
    29
    30    t = str;
    31    if (base == 16) {
    32      while (*t == 'f') {
    33        t++;
    34      }
    35    }
    36    else if (base == 8) {
    37      *t |= EXTENDSIGN(3, strlen(t));
    38      while (*t == '7') {
    39        t++;
    40      }
    41    }
    42    else if (base == 2) {
    43      while (*t == '1') {
    44        t++;
    45      }
    46    }
    47
    48    return t;
    49  }
