    52  sign_bits(int base, const char *p)
    53  {
    54    char c;
    55
    56    switch (base) {
    57    case 16:
    58      if (*p == 'X') c = 'F';
    59      else c = 'f';
    60      break;
    61    case 8:
    62      c = '7'; break;
    63    case 2:
    64      c = '1'; break;
    65    default:
    66      c = '.'; break;
    67    }
    68    return c;
