   118  {
   119    char sign = '\0';
   120    int left_align = 0;
   121    int zero_pad = 0;
   122
   123    if (flags & FSHARP) fmt |= 0x80;
   124    if (flags & FPLUS)  sign = '+';
   125    if (flags & FMINUS) left_align = 1;
   126    if (flags & FZERO)  zero_pad = 1;
